    Topic(
      id: 6,
      title: "Toshkent rasadxonasi",
      keywords: [
        "Toshkent rasadxonasi",
        "Maydanak rasadxonasi",
        "Hisorak tog'i",
        "astronomiya va aeronavtika muzeyi",
